/* Per-camera pre-capture view verification. Demo verdicts never enter live capture. */
let cgState={profiles:{},sources:[]},cgReport=null,cgReportMode=null,cgDemoBaselines={},cgDemoScenario='drift';
pages.push(['camera-check','采前相机检查']);
$('#nav').insertAdjacentHTML('afterbegin','<a href="#camera-check" data-page="camera-check"><svg viewBox="0 0 24 24"><path d="M3 7h5l2-3h4l2 3h5v13H3z M12 10a4 4 0 1 0 0 8a4 4 0 1 0 0-8"/></svg>采前相机检查</a>');
function cgSelect(){return $('#cg-camera')?.value||'camera_0'}
function cgRole(key){return key==='camera_0'?'腕部（默认角色，请核对）':key==='preview'?'独立预览 · 仅诊断':'固定侧视（请核对）'}
function cgForm(){const key=cgSelect(),profile=cgState.profiles[key];const cfg=profile?.config||{};for(const [id,v] of Object.entries({'cg-mount':cfg.mount||(key==='camera_0'?'wrist':'fixed'),'cg-method':cfg.mode||'aruco','cg-marker-id':cfg.marker_id??0,'cg-marker-size':(cfg.marker_size_m??.05)*1000,'cg-roi':(cfg.roi||[0,0,640,480]).join(','),'cg-pixel':cfg.shift_px??6,'cg-angle':cfg.angle_deg??2,'cg-mm':cfg.translation_mm??5,'cg-scale':cfg.scale_ratio??.03})){if($('#'+id))$('#'+id).value=v}if($('#cg-intrinsics'))$('#cg-intrinsics').value=profile?.intrinsics?JSON.stringify(profile.intrinsics):'';cgReport=null;if($('#cg-result'))$('#cg-result').innerHTML=cgResult()}
function cgReadConfig(){const intrinsicText=$('#cg-intrinsics').value.trim();return {mount:$('#cg-mount').value,mode:$('#cg-method').value,required:cgSelect()!=='preview',roi:$('#cg-roi').value.split(',').map(Number),marker_id:Number($('#cg-marker-id').value),marker_size_m:Number($('#cg-marker-size').value)/1000,shift_px:Number($('#cg-pixel').value),angle_deg:Number($('#cg-angle').value),translation_mm:Number($('#cg-mm').value),scale_ratio:Number($('#cg-scale').value),intrinsics:intrinsicText?JSON.parse(intrinsicText):undefined}}
function cgResult(){if(!cgReport)return '<div class="sensor-empty">先确认固定参照、保存基准，然后执行检测。检测失败不会被视为正常。</div>';const r=cgReport;const m=r.metrics||{};const status={pass:'位置检查通过',drift:'视角／位置存在偏差',unknown:'当前无法可靠判断'}[r.status];return `<div class="card-head"><h2>${status}</h2>${badge(pMode==='demo'?'模拟结果':r.status,r.status==='pass'?'':r.status==='drift'?'amber':'gray')}</div><div class="cg-metrics">${r.mode==='aruco'?[['位置差',m.translation_mm,'mm'],['姿态差',m.angle_deg,'°'],['重投影误差',m.reprojection_px,'px']].map(([t,v,u])=>`<div><small>${t}</small><strong>${Number.isFinite(v)?v.toFixed(2):'—'} <em>${u}</em></strong></div>`).join(''):[['图像偏移',m.shift_px,'px'],['平面旋转',m.angle_deg,'°'],['局部尺度',m.scale,'×']].map(([t,v,u])=>`<div><small>${t}</small><strong>${Number.isFinite(v)?v.toFixed(2):'—'} <em>${u}</em></strong></div>`).join('')}</div><ul class="cg-guidance">${(r.guidance||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="subtle">基准：${esc(r.baseline_id||'尚未建立')} · ${esc(r.key||'')}</p>${r.reference_preview?`<div class="cg-images"><figure><img src="${r.reference_preview}" alt="保存的相机基准"><figcaption>基准画面</figcaption></figure><figure><img src="${r.current_preview}" alt="当前相机画面"><figcaption>当前画面</figcaption></figure><figure><img src="${r.aligned_preview}" alt="配准或标记诊断预览"><figcaption>${esc(r.preview_note||'诊断预览')}</figcaption></figure></div>`:''}`}
views['camera-check']=()=>pHead('采前相机位置检查','两路固定侧视＋一路腕部相机。保存基准、检测偏差、调整复检，结果关联采集片段。',`<button onclick="cgRefresh()">刷新来源与基准</button>`)+`<div class="warning">工位参照建议：固定桌面、铝型材框架或固定 ArUco 标记。布帘、木块、工具和运动中的机械臂不应作为背景参照。腕部相机必须在相同参考关节姿态下检查。</div><div class="grid2"><section class="card fields"><div class="card-head"><h2>相机与检查策略</h2>${badge('采前质量门控','blue')}</div><label for="cg-camera">相机通道</label><select id="cg-camera" onchange="cgForm()">${['camera_0','camera_1','camera_2','preview'].map(k=>`<option value="${k}">${k} · ${cgRole(k)}</option>`).join('')}</select><div class="grid-equal"><div><label for="cg-mount">安装类型</label><select id="cg-mount"><option value="wrist">腕部相机</option><option value="fixed">固定侧视相机</option></select></div><div><label for="cg-method">检测方式</label><select id="cg-method"><option value="aruco">ArUco＋内参 · 相对三维位姿</option><option value="features">静态特征 · 平面视角一致性</option></select></div></div><div class="grid-equal"><div><label for="cg-marker-id">ArUco 4×4_50 标记 ID</label><input id="cg-marker-id" type="number" min="0" max="49" value="0"></div><div><label for="cg-marker-size">实测黑色外边长 mm</label><input id="cg-marker-size" type="number" min="5" max="2000" value="50"></div></div><label for="cg-roi">静态参照 ROI：x,y,宽,高（特征模式）</label><input id="cg-roi" value="0,0,640,480"><div class="grid-equal"><div><label for="cg-pixel">图像平面阈值 px</label><input id="cg-pixel" type="number" min=".1" step=".5" value="6"></div><div><label for="cg-angle">角度阈值 °</label><input id="cg-angle" type="number" min=".1" step=".1" value="2"></div><div><label for="cg-mm">相对位置阈值 mm</label><input id="cg-mm" type="number" min=".1" step=".5" value="5"></div><div><label for="cg-scale">尺度变化阈值（比例）</label><input id="cg-scale" type="number" min=".001" step=".01" value=".03"></div></div><label for="cg-intrinsics">相机内参 JSON（已有实际内参时可自动使用）</label><textarea id="cg-intrinsics" rows="3" placeholder='{"width":640,"height":480,"fx":实际值,"fy":实际值,"ppx":实际值,"ppy":实际值,"coeffs":[0,0,0,0,0],"model":"brown_conrady"}'></textarea><p class="subtle">GELLO 来源未携带内参时，使用对应序列号和分辨率的已标定内参。界面阈值仅为起始配置，需现场验证。</p><div class="actions"><button class="primary" onclick="cgSave()">确认摆位并保存新基准</button><button onclick="cgCheck()">检测 / 调整后复检</button></div><p class="subtle">固定标记必须保持不动；不会自动移动相机或机械臂。独立 preview 通道只做诊断，不能代替 GELLO 采集通道检查。</p><a href="downloads/aruco-4x4-50-id0.png" download>下载 ID0 标记图（打印后实测边长） ↓</a></section><section class="card"><h2>每次采集前的流程</h2><div class="pipeline-list">${[['01','建立环境基准','固定侧视逐路保存；腕部记录参考关节姿态'],['02','检测相机变化','有标记用位姿；无标记仅检测平面视角差异'],['03','给出调整指导','显示偏差量、坐标系与可靠性，调整后复检'],['04','检查通过再采集','本地采集前重新计算，不依赖演示结果']].map(([a,b,c])=>`<div class="node-row"><span class="node-icon">${a}</span><div><strong>${b}</strong><small>${c}</small></div></div>`).join('')}</div><div class="warning" style="margin-top:22px">图像对齐只提供平面诊断预览。三维场景的透视变化、遮挡和物体高度不能通过一张单应性图完整恢复。</div>${pMode==='demo'?`<label for="cg-demo-case">演示场景（不访问设备）</label><select id="cg-demo-case" onchange="cgDemoScenario=this.value"><option value="drift">相机视角偏移</option><option value="pass">相机位置一致</option><option value="unknown">参照遮挡 / 检测不可靠</option></select>`:''}<h3 style="margin-top:25px">基准登记</h3><div id="cg-profiles">${cgProfiles()}</div></section><section class="card wide"><div id="cg-result">${cgResult()}</div></section></div>`;
function cgProfiles(){const profiles=pMode==='demo'?cgDemoBaselines:cgState.profiles;return Object.keys(profiles).length?Object.entries(profiles).map(([k,p])=>`<div class="node-row"><div><strong>${esc(k)}</strong><small>${esc(p.id)} · ${esc(p.config?.mount||'演示')}</small></div>${badge('已登记')}</div>`).join(''):'<p>尚未登记基准。演示与实机基准相互独立。</p>'}
async function cgRefresh(){if(pMode==='demo'){toast('演示模式不读取实际相机');return}try{cgState=await pApi('camera-guard/status');if($('#cg-profiles'))$('#cg-profiles').innerHTML=cgProfiles();cgForm();toast('已读取相机来源和持久化基准')}catch(e){toast(e.message)}}
async function cgSave(){const camera=cgSelect();let config;try{config=cgReadConfig()}catch(e){return toast('内参 JSON 格式无效：'+e.message)}if(pMode==='demo'){cgDemoBaselines[camera]={id:'DEMO-CB-'+Date.now().toString().slice(-6),config};$('#cg-profiles').innerHTML=cgProfiles();return toast('已保存模拟基准，不用于实机门控')}try{await pApi('camera-guard/baseline',{camera,config});cgState=await pApi('camera-guard/status');$('#cg-profiles').innerHTML=cgProfiles();toast('新基准版本已保存；旧基准文件保留')}catch(e){toast(e.message)}}
async function cgCheck(){
  const camera=cgSelect(),mode=pMode;let report;
  if(mode==='demo'){
    const baseline=cgDemoBaselines[camera];
    report={key:camera,baseline_id:baseline?.id,status:baseline?cgDemoScenario:'unknown',mode:'features',
      metrics:cgDemoScenario==='pass'?{shift_px:.8,angle_deg:.1,scale:1.001}:{shift_px:14.2,angle_deg:3.1,scale:1.04},
      guidance:!baseline?['请先保存演示基准。']:cgDemoScenario==='unknown'?['参照被遮挡，当前不能可靠判断；实机门控会阻止开始采集。']:cgDemoScenario==='pass'?['模拟视角一致。实机仍需按实际输入重新检测。']:['模拟画面偏移14.2px；逐步调整后复检。','此演示不代表实际相机移动了多少毫米。']};
  }else{
    try{report=await pApi('camera-guard/check?camera='+encodeURIComponent(camera))}catch(e){return toast(e.message)}
  }
  if(mode!==pMode||camera!==cgSelect())return;
  cgReport=report;cgReportMode=mode;
  if($('#cg-result'))$('#cg-result').innerHTML=cgResult();
}
const cgPreviousCapture=pCapture;pCapture=async function(action){if(pMode==='live'&&action==='start'){try{await pApi('capture/start',{tactile:$('#p-touch-enable').checked,require_camera_check:true});await pPoll();render();toast('所有采集相机检查通过，等待有效数据帧')}catch(e){toast(e.message+'；请到“采前相机检查”处理。')}return}return cgPreviousCapture(action)};
const cgDataView=views['edge-data'];views['edge-data']=()=>`<div class="cg-banner">采集前自动检查 RGB 相机基准与腕部参考姿态。<a href="#camera-check">进入采前相机检查 →</a></div>`+cgDataView();
const cgOverview=views.ur5e;views.ur5e=()=>cgOverview()+`<section class="card" style="margin-top:22px"><div class="card-head"><h2>相机位置一致性</h2><a href="#camera-check">配置基准与调整指导 →</a></div><p>两路固定侧视逐路比较，一路腕部相机先核对参考关节姿态。支持标记相对位姿、平面配准诊断和采集门控。</p></section>`;
const cgOriginalProfiles=cgProfiles;
cgProfiles=function(){return cgOriginalProfiles()+(pMode==='live'?`<h3>当前来源</h3>${cgState.sources.map(s=>`<div class="node-row"><div><strong>${esc(s.key)}</strong><small>${esc(s.identity)} · ${s.width}×${s.height}</small></div>${badge(s.fresh?'有效':'已过期',s.fresh?'':'amber')}</div>`).join('')||'<p>尚无实际 RGB 来源</p>'}`:'')};
async function cgCurrent(){if(pMode==='demo')return toast('当前画面预览仅在本地实机模式读取；演示可保存模拟基准后检测。');try{const f=await pApi('camera-guard/frame?camera='+encodeURIComponent(cgSelect()));$('#cg-result').innerHTML=`<h2>当前实际画面 · ${esc(f.key)}</h2><p>${esc(f.identity)} · ${f.width}×${f.height} · 请确认安装角色和固定参照</p><div class="cg-images"><figure><img src="${f.image}" alt="当前采集通道的实际 RGB 画面"><figcaption>独立快照；保存基准时会重新读取新鲜帧</figcaption></figure></div>`;if(!$('#cg-intrinsics').value.trim()&&f.intrinsics)$('#cg-intrinsics').value=JSON.stringify(f.intrinsics)}catch(e){toast(e.message)}}
const cgOriginalView=views['camera-check'];views['camera-check']=()=>cgOriginalView().replace('<button onclick="cgRefresh()">','<button onclick="cgCurrent()">查看当前画面</button><button onclick="cgRefresh()">');
const cgOriginalResult=cgResult;cgResult=function(){return cgReport&&cgReportMode!==pMode?'<div class="sensor-empty">模式已变化，请重新检测当前来源。演示结果不会用于实机。</div>':cgOriginalResult()};
render();
